package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)

	var S, T string
	var counter int

	for counter < 2 {
		line, _ := reader.ReadString('\n')
		if counter == 0 {
			S = line
		} else {
			T = line

			ans := "YES"
			j := 0
			for i := len(T) - 1; i >= 0; i-- {
				if T[i] != S[j] {
					ans = "NO"
					break
				}
				j++
			}

			fmt.Println(ans)
		}
		counter++
	}
}
